def column_totals(rows):
    if not rows:
        return []
    num_cols = len(rows[0])
    totals = []
    for i in range(num_cols):
        col_values = [row[i] for row in rows]
        total = 0
        has_numeric = False
        for v in col_values:
            if isinstance(v, (int, float)):
                total += v
                has_numeric = True
        if has_numeric:
            totals.append(total)
        else:
            totals.append("")
    return totals

